    inventory = json.loads(
        (REPO_ROOT / "schemas" / "packaging-inventory.json").read_text(encoding="utf-8")
    )
    assert inventory["version"] == 52
    assert inventory["min_validator_count"] == 196
    assert sorted(vm.VALIDATORS) == inventory["validator_names"]

    for name, _fn, phrases, inv_key in modules:
        assert name in vm.VALIDATORS
        assert name in inventory["validator_names"]
        assert inv_key in inventory
        assert inventory[inv_key] == list(phrases)
        assert len(phrases) >= 2

    # Adjacent leftover slices stay live but are intentionally excluded
    assert "constitution-crypto" in vm.VALIDATORS  # merged #156
    assert "goose-howto" in vm.VALIDATORS  # merged #147
    assert "prompt-usage-detail" in vm.VALIDATORS  # merged #144
    assert "constitution-crypto" not in {m[0] for m in modules}
    assert "goose-howto" not in {m[0] for m in modules}
    assert "security" not in {m[0] for m in modules}  # closed #158 leftover
    assert "goose-timeouts" not in vm.VALIDATORS  # closed #157 invent sibling

    for goose_name in (
        "goose-howto",
        "goose-orchestration",
        "goose-quantum-task",
    ):
        assert goose_name in vm.VALIDATORS


