_IMPLEMENTATION_RESIDUAL_NAMES: tuple[str, ...] = (
    "implementation-guide",
    "implementation-quickstart",
    "implementation-phases",
    "implementation-tools",
    "implementation-success",
    "implementation-issues",
    "implementation-faq",
    "implementation-support",
)


def _implementation_residual_modules() -> list[
    tuple[str, object, tuple[str, ...], str]
]:
    """Map the eight existing implementation-guide phrase-lock validators."""
    modules: list[tuple[str, object, tuple[str, ...], str]] = []
    for name in _IMPLEMENTATION_RESIDUAL_NAMES:
        suffix = name.removeprefix("implementation-").replace("-", "_")
        modules.append(
            (
                name,
                getattr(vm, f"validate_{name.replace('-', '_')}"),
                getattr(vm, f"IMPLEMENTATION_{suffix.upper()}_REQUIRED_PHRASES"),
                f"implementation_{suffix}_required_phrases",
            )
        )
    return modules


def _implementation_residual_locked_text() -> str:
    """Union of locked phrases + historic four agents for implementation-guide."""
    lines: list[str] = []
    seen: set[str] = set()
    ordered: list[str] = []
    for _name, _fn, phrases, _key in _implementation_residual_modules():
        ordered.extend(phrases)
    ordered.extend(vm.DOCUMENTED_AGENTS)
    for phrase in sorted(ordered, key=len, reverse=True):
        if phrase not in seen:
            seen.add(phrase)
            lines.append(phrase)
    return "\n".join(lines) + "\n"


def _implementation_packaging_inventory_findings(
    **overrides: object,
) -> list[vm.Finding]:
    """Write a temp packaging inventory with overrides and validate it."""
    with tempfile.TemporaryDirectory(prefix="implementation-residual-inv-") as raw:
        root = Path(raw)
        _copy_schemas(root)
        payload = _inventory_payload()
        payload.update(overrides)
        for rel in payload["required_paths"]:
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            if not target.exists():
                target.write_text("ok\n", encoding="utf-8")
        (root / "schemas" / "packaging-inventory.json").write_text(
            json.dumps(payload),
            encoding="utf-8",
        )
        return vm.validate_packaging_inventory(root)


