def test_implementation_residual_empty_maps_and_empty_doc(tmp_path: Path) -> None:
    """Empty / whitespace / header-only guide + empty implementation phrase maps."""
    modules = _implementation_residual_modules()
    for name, fn, _phrases, _key in modules:
        findings = fn(tmp_path)
