def test_implementation_residual_inventory_mismatch_matrix() -> None:
    """Empty / dup / blank / seed mismatches for every implementation_* inventory key."""
    modules = _implementation_residual_modules()
    for _name, _fn, phrases, key in modules:
        if key == "implementation_guide_required_phrases":
            findings = _implementation_packaging_inventory_findings(**{key: []})
            assert any(
                "implementation_guide_required_phrases" in f.message
                and "should be non-empty" in f.message
                for f in findings
            ), key

            findings = _implementation_packaging_inventory_findings(
                **{key: [phrases[0], phrases[0], *phrases[1:]]}
            )
            assert any(
                "implementation_guide_required_phrases" in f.message
                and "non-unique" in f.message
                for f in findings
            ), key

            findings = _implementation_packaging_inventory_findings(
                **{key: ["ok", "  "]}
            )
            assert any(
                "implementation_guide_required_phrases" in f.message
                and "do not match" in f.message
                for f in findings
            ), key

            findings = _implementation_packaging_inventory_findings(
                **{key: [phrases[0]]}
            )
            assert any(
                "implementation_guide_required_phrases" in f.message
                and "do not match" in f.message
                for f in findings
            ), key
            continue

        payload = _inventory_payload()
        payload[key] = []
        findings = vm._inventory_lock_consistency(
            payload, schema_path="schemas/packaging-inventory.json"
        )
        assert any(f"{key} must not be empty" in f.message for f in findings), key

        payload = _inventory_payload()
        payload[key] = [phrases[0], phrases[0], *phrases[1:]]
        findings = vm._inventory_lock_consistency(
            payload, schema_path="schemas/packaging-inventory.json"
        )
        assert any(f"{key} must be unique" in f.message for f in findings), key

        payload = _inventory_payload()
        payload[key] = ["ok", "  "]
        findings = vm._inventory_lock_consistency(
            payload, schema_path="schemas/packaging-inventory.json"
        )
        assert any(
            f"{key} entries must be non-empty strings" in f.message for f in findings
        ), key

        payload = _inventory_payload()
        payload[key] = ["seed-only-token"]
        findings = vm._inventory_lock_consistency(
            payload, schema_path="schemas/packaging-inventory.json"
        )
        assert any(
            key in f.message
            and (
                "must include" in f.message
                or "must mention" in f.message
                or "must refuse" in f.message
                or "must name" in f.message
            )
            for f in findings
        ), key


def test_implementation_residual_concurrent_validate_races(tmp_path: Path) -> None:
    """Concurrent readers/writers against IMPLEMENTATION-GUIDE.md must not crash."""
    modules = _implementation_residual_modules()
    live_fns = [fn for _name, fn, _phrases, _key in modules]

    def _read_live() -> list[vm.Finding]:
        out: list[vm.Finding] = []
        for fn in live_fns:
            out.extend(fn(REPO_ROOT))
        return out

    errors: list[BaseException] = []
    with ThreadPoolExecutor(max_workers=16) as pool:
        futures = [pool.submit(_read_live) for _ in range(48)]
        for fut in as_completed(futures):
            try:
                assert fut.result() == []
            except BaseException as exc:  # noqa: BLE001 — collect race failures
                errors.append(exc)
    assert errors == []

    locked = _implementation_residual_locked_text()
    path = tmp_path / "IMPLEMENTATION-GUIDE.md"
    _write(path, locked)
    for name, fn, _phrases, _key in modules:
        assert fn(tmp_path) == [], name

    stop = threading.Event()
    race_errors: list[BaseException] = []

    def _writer() -> None:
        flip = False
        while not stop.is_set():
            try:
                if flip:
                    path.write_text(locked, encoding="utf-8")
                else:
                    path.write_text("\n", encoding="utf-8")
                flip = not flip
            except BaseException as exc:  # noqa: BLE001
                race_errors.append(exc)
                return

    def _reader() -> None:
        while not stop.is_set():
            try:
                for fn in live_fns:
                    fn(tmp_path)
            except BaseException as exc:  # noqa: BLE001
                race_errors.append(exc)
                return

    threads = [
        threading.Thread(target=_writer),
        threading.Thread(target=_reader),
        threading.Thread(target=_reader),
        threading.Thread(target=_reader),
    ]
    for t in threads:
        t.start()
    time.sleep(0.35)
    stop.set()
    for t in threads:
        t.join(timeout=2.0)
    assert race_errors == []

    def _empty_map_check(key: str) -> bool:
        if key == "implementation_guide_required_phrases":
            findings = _implementation_packaging_inventory_findings(**{key: []})
            return any(
                "implementation_guide_required_phrases" in f.message
                and "should be non-empty" in f.message
                for f in findings
            )
        payload = _inventory_payload()
        payload[key] = []
        findings = vm._inventory_lock_consistency(
            payload, schema_path="schemas/packaging-inventory.json"
        )
        return any(f"{key} must not be empty" in f.message for f in findings)

    keys = [key for _n, _f, _p, key in modules]
    with ThreadPoolExecutor(max_workers=8) as pool:
        futs = [pool.submit(_empty_map_check, k) for k in keys for _ in range(2)]
        assert all(fut.result() for fut in as_completed(futs))


