# TOKENMAXX HEAVY: actionlint/workflow + link-check residuals after #184
# ---------------------------------------------------------------------------

_ACTIONLINT_LINKCHECK_RESIDUAL_NAMES: tuple[str, ...] = (
    "ci",
    "ci-actions",
    "link-check",
    "actionlint-shell",
    "ci-job-names",
    "ci-runs-on",
    "ci-artifacts",
)

_ACTIONLINT_LINKCHECK_CI_REL = ".github/workflows/ci.yml"


def _actionlint_linkcheck_residual_modules() -> list[tuple[str, object]]:
    """Map the seven existing actionlint/workflow + link-check CI validators."""
    return [(name, vm.VALIDATORS[name]) for name in _ACTIONLINT_LINKCHECK_RESIDUAL_NAMES]


def _actionlint_linkcheck_locked_ci_yaml() -> str:
    """Live locked ci.yml text used as the residual fixture baseline."""
    return (REPO_ROOT / _ACTIONLINT_LINKCHECK_CI_REL).read_text(encoding="utf-8")


def _write_ci_yaml(tmp_path: Path, text: str) -> Path:
    path = tmp_path / _ACTIONLINT_LINKCHECK_CI_REL
    _write(path, text)
    return path


def _drop_ci_job(text: str, job_id: str) -> str:
    """Remove one top-level job mapping from locked ci.yml text."""
    lines = text.splitlines()
    out: list[str] = []
    skipping = False
    for line in lines:
        if line.startswith(f"  {job_id}:"):
            skipping = True
            continue
        if skipping and line.startswith("  ") and not line.startswith("    "):
            skipping = False
        if skipping:
            continue
        out.append(line)
    return "\n".join(out) + "\n"


def _set_ci_job_key_scalar(text: str, job_id: str, key: str, value: str) -> str:
    """Replace a job's `key:` block header with a scalar (drops nested keys)."""
    lines = text.splitlines()
    out: list[str] = []
    in_job = False
    replaced = False
    skip_nested = False
    for line in lines:
        if line.startswith(f"  {job_id}:"):
            in_job = True
        elif in_job and line.startswith("  ") and not line.startswith("    "):
            in_job = False
            skip_nested = False
        if skip_nested:
            # Keep skipping the replaced block, including blank lines inside it.
            if (not line.strip()) or line.startswith("      "):
                continue
            skip_nested = False
        if in_job and (not replaced) and line.strip() == f"{key}:":
            out.append(f"    {key}: {value}")
            replaced = True
            skip_nested = True
            continue
        out.append(line)
    return "\n".join(out) + "\n"


