def test_hydration_security_handoff_after248_ci_mangle_cross_isolation(
    tmp_path: Path,
) -> None:
    """After #248: mangled CI fails actionlint/linkcheck; hyd/sec/handoff stay green."""
    _write_hydration_security_handoff_after248_docs(tmp_path)
    for name, fn in _hydration_security_handoff_after248_modules():
        assert fn(tmp_path) == [], name

    base = _actionlint_linkcheck_locked_ci_yaml()
    lychee_block = (
        "      - name: Check links\n"
        "        uses: lycheeverse/lychee-action@v2\n"
        "        with:\n"
        f"          args: {vm.CI_LINK_CHECK_ARGS}\n"
        "          fail: true\n"
        "        env:\n"
        "          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n"
    )
    empty_with = base.replace(
        lychee_block,
        "      - name: Check links\n"
        "        uses: lycheeverse/lychee-action@v2\n"
        "        with: {}\n",
    )
    assert empty_with != base
    _write_ci_yaml(tmp_path, empty_with)
    assert vm.validate_link_check(tmp_path)
    for name, fn in _hydration_security_handoff_after248_modules():
        assert fn(tmp_path) == [], name

    extra_shell_lines = base.splitlines()
    out: list[str] = []
    in_al = False
    injected = False
    for line in extra_shell_lines:
        if line.startswith("  actionlint:"):
            in_al = True
        elif in_al and line.startswith("  ") and not line.startswith("    "):
            in_al = False
        if (
            in_al
            and (not injected)
            and line.strip() == "- uses: actions/checkout@v7"
        ):
            out.append(line)
            out.append("        shell: powershell")
            injected = True
            continue
        out.append(line)
    _write_ci_yaml(tmp_path, "\n".join(out) + "\n")
    assert injected
    assert vm.validate_actionlint_shell(tmp_path)
    for name, fn in _hydration_security_handoff_after248_modules():
        assert fn(tmp_path) == [], name

    # Live tip siblings from #248 / #242 / #236 / #229 remain green.
    assert vm.validate_link_check(REPO_ROOT) == []
    assert vm.validate_actionlint_shell(REPO_ROOT) == []
    assert vm.validate_hydration_phase4(REPO_ROOT) == []
    assert vm.validate_security_packaging(REPO_ROOT) == []
    assert vm.validate_constitution_handoff(REPO_ROOT) == []
    assert vm.validate_scratchpad(REPO_ROOT) == []
    assert "markdownlint" in vm.VALIDATORS
    assert "markdownlint" not in _HYDRATION_SECURITY_HANDOFF_AFTER248_NAMES
    assert "actionlint-shell" not in _HYDRATION_SECURITY_HANDOFF_AFTER248_NAMES
    assert "link-check" not in _HYDRATION_SECURITY_HANDOFF_AFTER248_NAMES

def test_hydration_security_handoff_after248_concurrent_four_doc_races(
    tmp_path: Path,
) -> None:
    """after248 leftover: concurrent readers/writers across four docs must not crash."""
    leftover_fns = [fn for _n, fn in _hydration_security_handoff_after248_modules()]

    def _read_live() -> list[vm.Finding]:
        out: list[vm.Finding] = []
        for fn in leftover_fns:
            out.extend(fn(REPO_ROOT))
        return out

    errors: list[BaseException] = []
    with ThreadPoolExecutor(max_workers=16) as pool:
        futures = [pool.submit(_read_live) for _ in range(48)]
        for fut in as_completed(futures):
            try:
                assert fut.result() == []
            except BaseException as exc:  # noqa: BLE001 — collect race failures
                errors.append(exc)
    assert errors == []

    hyd_path = tmp_path / _HYDRATION_SECURITY_CROSS_DOC
    sec_path = tmp_path / "SECURITY.md"
    agents_path = tmp_path / _MEMORY_HANDOFF_DOC
    scratch_path = tmp_path / _MEMORY_HANDOFF_SCRATCHPAD_DOC
    hyd_locked = _hydration_residual_locked_text()
    sec_locked = _security_residual_locked_text()
    agents_locked = _memory_handoff_constitution_locked_text()
    scratch_locked = _locked_scratchpad_text()
    _write_hydration_security_handoff_after248_docs(tmp_path)
    assert vm.validate_hydration_phase4(tmp_path) == []
    assert vm.validate_security_packaging(tmp_path) == []
    assert vm.validate_constitution_handoff(tmp_path) == []
    assert vm.validate_scratchpad(tmp_path) == []

    stop = threading.Event()
    race_errors: list[BaseException] = []

    def _writer() -> None:
        flip = False
        while not stop.is_set():
            try:
                if flip:
                    hyd_path.write_text(hyd_locked, encoding="utf-8")
                    sec_path.write_text(sec_locked, encoding="utf-8")
                    agents_path.write_text(agents_locked, encoding="utf-8")
                    scratch_path.write_text(scratch_locked, encoding="utf-8")
                else:
                    hyd_path.write_text("\n", encoding="utf-8")
                    sec_path.write_text("\n", encoding="utf-8")
                    agents_path.write_text("\n", encoding="utf-8")
                    scratch_path.write_text("\n", encoding="utf-8")
                flip = not flip
            except BaseException as exc:  # noqa: BLE001
                race_errors.append(exc)
                return

    def _reader() -> None:
        while not stop.is_set():
            try:
                for fn in leftover_fns:
                    fn(tmp_path)
            except BaseException as exc:  # noqa: BLE001
                race_errors.append(exc)
                return

    threads = [
        threading.Thread(target=_writer),
        threading.Thread(target=_reader),
        threading.Thread(target=_reader),
        threading.Thread(target=_reader),
    ]
    for t in threads:
        t.start()
    time.sleep(0.35)
    stop.set()
    for t in threads:
        t.join(timeout=2.0)
    assert race_errors == []

