# through #300 (Claude/routing leftover after #289) / #289 / #279 / #270 /
# #265 / #264 / #258 / #253 / #248. Distinct unsaturated residual edges beyond
# merged #248 after236 suite / #300 / #289 / #279 / #270 / #265 / #264 / #258 /
# #253 / #242 / #236 / #229 / #224 / #219 / #209 / #208 / #202 / #200 / #195 /
# #188. EXISTING seven CI fixtures only (v52 / 196). Prefer actionlint +
# linkcheck niche only (not markdownlint / not prompts+flows / not goose /
# not hydration / not Claude-routing). Supersedes closed CONFLICTING
# #302/#294/#280/#283/#274/#266/#256 (same leftover on pre-#300 / pre-#289 /
# pre-#279 / pre-#270 / pre-#265 / pre-#264 tips).
# ---------------------------------------------------------------------------

def _replace_ci_job_with_scalar(text: str, job_id: str, value: str) -> str:
    """Replace an entire top-level job mapping with a scalar value."""
    lines = text.splitlines()
    out: list[str] = []
    skipping = False
    for line in lines:
        if line.startswith(f"  {job_id}:"):
            out.append(f"  {job_id}: {value}")
            skipping = True
            continue
        if skipping and line.startswith("  ") and not line.startswith("    "):
            skipping = False
        if skipping:
            continue
        out.append(line)
    return "\n".join(out) + "\n"


def _set_ci_job_steps_scalar(text: str, job_id: str, value: str) -> str:
    """Replace a job's steps: block with a scalar (drops nested step items)."""
    lines = text.splitlines()
    out: list[str] = []
    in_job = False
    skip_nested = False
    replaced = False
    for line in lines:
        if line.startswith(f"  {job_id}:"):
            in_job = True
        elif in_job and line.startswith("  ") and not line.startswith("    "):
            in_job = False
            skip_nested = False
        if skip_nested:
            if (not line.strip()) or line.startswith("      "):
                continue
            skip_nested = False
        if in_job and (not replaced) and line.strip() == "steps:":
            out.append(f"    steps: {value}")
            replaced = True
            skip_nested = True
            continue
        out.append(line)
    return "\n".join(out) + "\n"


