def test_actionlint_linkcheck_after300_tab_ideographic_wj_lookalikes(
    tmp_path: Path,
) -> None:
    """Tip-after-#279: tab/ideographic/word-joiner lookalikes beyond #280 ZWSP."""
    base = _actionlint_linkcheck_locked_ci_yaml()
    rel = _ACTIONLINT_LINKCHECK_CI_REL

    tab_shell = base.replace(
        f"shell: {vm.CI_ACTIONLINT_SHELL}",
        "shell: \tbash",
        1,
    )
    _write_ci_yaml(tmp_path, tab_shell)
    findings = vm.validate_actionlint_shell(tmp_path)
    assert any("\\tbash" in f.message or "\tbash" in f.message for f in findings)

    ideo_shell = base.replace(
        f"shell: {vm.CI_ACTIONLINT_SHELL}",
        "shell: bash\u3000",
        1,
    )
    _write_ci_yaml(tmp_path, ideo_shell)
    findings = vm.validate_actionlint_shell(tmp_path)
    assert any("\\u3000" in f.message or "\u3000" in f.message for f in findings)

    # NEL/U+0085 is a YAML line-break — use word-joiner so the scalar stays one line.
    wj_args = base.replace(
        vm.CI_LINK_CHECK_ARGS,
        vm.CI_LINK_CHECK_ARGS.replace("--verbose", "--ver\u2060bose"),
    )
    _write_ci_yaml(tmp_path, wj_args)
    findings = vm.validate_link_check(tmp_path)
    assert any("link-check args must be" in f.message for f in findings)
    assert vm.Finding(rel, "link-check lychee args lock not found") in findings
    assert vm.validate_actionlint_shell(tmp_path) == []

    wj_name = base.replace("name: Link Check", "name: Link\u2060 Check")
    _write_ci_yaml(tmp_path, wj_name)
    assert any(
        "Link\\u2060 Check" in f.message or "\u2060" in f.message
        for f in vm.validate_ci_job_names(tmp_path)
    )

    wj_id = base.replace(
        f"id: {vm.CI_ACTIONLINT_STEP_ID}",
        f"id: {vm.CI_ACTIONLINT_STEP_ID}\u2060",
    )
    _write_ci_yaml(tmp_path, wj_id)
    assert vm.validate_actionlint_shell(tmp_path) == [
        vm.Finding(
            rel,
            f"actionlint job must include step id {vm.CI_ACTIONLINT_STEP_ID!r}",
        )
    ]

    _write_ci_yaml(tmp_path, base)
    assert vm.validate_actionlint_shell(tmp_path) == []
    assert vm.validate_link_check(tmp_path) == []
    assert vm.validate_ci_job_names(tmp_path) == []


