def test_actionlint_linkcheck_after300_concurrency_absent_and_perms_write_one(
    tmp_path: Path,
) -> None:
    """Tip-after-#279: drop concurrency + contents:write on actionlint only."""
    base = _actionlint_linkcheck_locked_ci_yaml()
    rel = _ACTIONLINT_LINKCHECK_CI_REL

    no_conc = base.replace(
        "concurrency:\n"
        "  group: ci-${{ github.workflow }}-${{ github.ref }}\n"
        "  cancel-in-progress: true\n\n",
        "",
    )
    assert "concurrency:" not in no_conc
    _write_ci_yaml(tmp_path, no_conc)
    findings = vm.validate_ci_workflow(tmp_path)
    assert vm.Finding(rel, "CI workflow must define concurrency.group") in findings
    assert vm.validate_link_check(tmp_path) == []
    assert vm.validate_actionlint_shell(tmp_path) == []

    # contents: write only on actionlint job (first occurrence after actionlint:).
    lines = base.splitlines()
    out: list[str] = []
    in_actionlint = False
    replaced = False
    for line in lines:
        if line.startswith("  actionlint:"):
            in_actionlint = True
        elif in_actionlint and line.startswith("  ") and not line.startswith("    "):
            in_actionlint = False
        if (
            in_actionlint
            and (not replaced)
            and line.strip() == "contents: read"
        ):
            out.append(line.replace("contents: read", "contents: write"))
            replaced = True
            continue
        out.append(line)
    one_write = "\n".join(out) + "\n"
    assert replaced
    _write_ci_yaml(tmp_path, one_write)
    findings = vm.validate_ci_workflow(tmp_path)
    assert (
        vm.Finding(
            rel,
            (
                "CI job actionlint permissions.contents must be "
                f"{vm.CI_PERMISSIONS_CONTENTS!r}, found 'write'"
            ),
        )
        in findings
    )
    assert not any(
        "link-check" in f.message and "permissions.contents" in f.message
        for f in findings
    )
    assert vm.validate_link_check(tmp_path) == []
    assert vm.validate_actionlint_shell(tmp_path) == []
    assert vm.validate_ci_runs_on(tmp_path) == []

    _write_ci_yaml(tmp_path, base)
    assert vm.validate_ci_workflow(tmp_path) == []


