def test_actionlint_linkcheck_after300_triple_surface_concurrent_races(
    tmp_path: Path,
) -> None:
    """Tip-after-#279: concurrent triple mangle (link args + shell + runs-on)."""
    modules = _actionlint_linkcheck_residual_modules()
    fns = [fn for _n, fn in modules]
    base = _actionlint_linkcheck_locked_ci_yaml()
    link_broken = base.replace(vm.CI_LINK_CHECK_ARGS, "--after300-triple-race")
    al_broken = base.replace(
        f"shell: {vm.CI_ACTIONLINT_SHELL}",
        "shell: pwsh",
        1,
    )
    runs_broken = base.replace(
        "runs-on: ubuntu-latest",
        "runs-on: Ubuntu-latest",
        1,
    )
    ci_path = tmp_path / _ACTIONLINT_LINKCHECK_CI_REL
    _write(ci_path, base)
    for name, fn in modules:
        assert fn(tmp_path) == [], name

    stop = threading.Event()
    race_errors: list[BaseException] = []

    def _writer() -> None:
        flip = 0
        while not stop.is_set():
            try:
                payload = (base, link_broken, al_broken, runs_broken)[flip % 4]
                ci_path.write_text(payload, encoding="utf-8")
                flip += 1
            except BaseException as exc:  # noqa: BLE001
                race_errors.append(exc)
                return

    def _reader() -> None:
        while not stop.is_set():
            try:
                for fn in fns:
                    fn(tmp_path)
            except BaseException as exc:  # noqa: BLE001
                race_errors.append(exc)
                return

    threads = [
        threading.Thread(target=_writer),
        threading.Thread(target=_reader),
        threading.Thread(target=_reader),
        threading.Thread(target=_reader),
    ]
    for t in threads:
        t.start()
    time.sleep(0.45)
    stop.set()
    for t in threads:
        t.join(timeout=2.0)
    assert race_errors == []

    errors: list[BaseException] = []
    with ThreadPoolExecutor(max_workers=12) as pool:
        futures = [
            pool.submit(
                lambda: [
                    finding
                    for _n, fn in modules
                    for finding in fn(REPO_ROOT)
                ]
            )
            for _ in range(36)
        ]
        for fut in as_completed(futures):
            try:
                assert fut.result() == []
            except BaseException as exc:  # noqa: BLE001
                errors.append(exc)
    assert errors == []

    # Live tip green under --only isolation for the seven residual modules.
    assert vm.run_all_validations(
        REPO_ROOT, only=list(_ACTIONLINT_LINKCHECK_RESIDUAL_NAMES)
    ) == []


